mapper.select:
select /* O.dhncorp.countAllBySearchParamWithType */
    count(1) as cnt
from (
    select 1
    from ${msg_table}
    where REQDTTM >= sysdate - 14
    AND NVL(REQDTTM, sysdate) <= sysdate
    and TYPE = #{msg_type}
    and STATUS = '100'
    and PRIORITY = #{priority}
    and rownum = 1
)

mapper.update:
update /* O.dhncorp.updateGroupBySearchParamWithType */
    ${msg_table}
set TYPE = #{group_no}
where SEQNO IN (
    select SEQNO
from ${msg_table}
  where REQDTTM >= sysdate - 14
  AND NVL(REQDTTM, sysdate) <= sysdate
  and TYPE = #{msg_type}
  and STATUS = '100'
  and PRIORITY = #{priority}
  and ROWNUM <= 500
    )

update /*+ INDEX(TS_SMS_2020 IDX_TS_SMS_2020_TEMP_2025_07) */ /* O.dhncorp.updateDateMakeBySeqNOWithType_T0507 */
    ${msg_table}
set STATUS = '102',
    TYPE = #{msg_type}
WHERE TYPE = #{group_no}

update /*+ INDEX(TS_SMS_2020 IDX_TS_SMS_2020_TEMP_2025_07) */ /* O.dhncorp.updateSendFailBySearchParamWithType_T0507 */
    ${msg_table}
set STATUS = '100',
    TYPE = #{msg_type}
WHERE TYPE = #{group_no}
